"""Extract the supplied WebUI snapshot; never contact or write to a controller.

Run with Python 3: extract_channel_map.py [--check].
--check compares generated bytes without modifying any file.
"""
import argparse
import hashlib
import json
import re
from collections import Counter
from pathlib import Path
import xml.etree.ElementTree as ET

ROOT = Path(__file__).resolve().parents[1]
SOURCE = 'Sources/wb-webui (5).conf'


def encoded(value):
    return (json.dumps(value, ensure_ascii=False, indent=2) + '\n').encode('utf-8')


def cell(value):
    return str(value).replace('|', '\\|').replace('\n', '<br>')


def table(headers, rows):
    return '\n'.join(['| ' + ' | '.join(headers) + ' |',
                      '| ' + ' | '.join(['---'] * len(headers)) + ' |'] +
                     ['| ' + ' | '.join(cell(v) for v in row) + ' |' for row in rows])


def extract():
    raw = (ROOT / SOURCE).read_bytes()
    conf = json.loads(raw)
    sha = hashlib.sha256(raw).hexdigest()
    dashboards = conf['dashboards']
    widgets = conf['widgets']
    assert len({w['id'] for w in widgets}) == len(widgets)
    widget_ids = {w['id'] for w in widgets}
    assert all(w in widget_ids for d in dashboards for w in d.get('widgets', []))
    membership = {w['id']: [{'id': d['id'], 'name': d['name']} for d in dashboards
                          if w['id'] in d.get('widgets', [])] for w in widgets}
    occurrences = []
    separators = []
    for wi, w in enumerate(widgets):
        section = ''
        for ci, c in enumerate(w['cells']):
            pointer = f'/widgets/{wi}/cells/{ci}'
            if c.get('type') == 'separator':
                section = c.get('name', '')
                separators.append({'source_pointer': pointer, 'cell': c})
                continue
            assert '/' in c['id'], (pointer, c)
            occurrences.append({'wb_id': c['id'], 'source_pointer': pointer + '/id',
                                'kind': 'widget', 'widget_id': w['id'],
                                'widget_name': w['name'], 'dashboards': membership[w['id']],
                                'section_label': section, 'signal_label': c.get('name', ''),
                                'ui_type': c.get('type'), 'raw_cell': c,
                                'scope': 'object' if any(d['id'] in ('mo1','mo2','mo3','mo4')
                                                                       for d in membership[w['id']]) else 'demo_service'})
    for di, d in enumerate(dashboards):
        for pi, param in enumerate(d.get('svg', {}).get('params', [])):
            for mode in ('read', 'write', 'visible', 'style'):
                spec = param.get(mode, {})
                if spec.get('channel'):
                    assert '/' in spec['channel']
                    occurrences.append({'wb_id': spec['channel'],
                        'source_pointer': f'/dashboards/{di}/svg/params/{pi}/{mode}/channel',
                        'kind': 'svg_param', 'dashboard_id': d['id'], 'dashboard_name': d['name'],
                        'element_id': param['id'], 'mode': mode, 'enabled': spec.get('enable'),
                        'raw_binding': spec, 'scope': 'demo_service' if d['id']=='dashboard2' else 'object'})
    channels = []
    for wb_id in dict.fromkeys(o['wb_id'] for o in occurrences):
        device, control = wb_id.split('/', 1)
        refs = [o for o in occurrences if o['wb_id'] == wb_id]
        address = None
        if m := re.fullmatch(r'wb-mio-gpio_(\d+):(\d+)', device):
            address = {'address_token': m[1], 'module_token': m[2],
                       'status': 'Предположение: адрес/модуль по имени; serial-конфиг не предоставлен'}
        elif m := re.fullmatch(r'wb-ms_(\d+)', device):
            address = {'address_token': m[1], 'status': 'Предположение: адрес по имени; модель и slave_id не проверены'}
        channels.append({'wb_id': wb_id, 'device_id': device, 'control_id': control,
            'mqtt_topic_derived': f'/devices/{device}/controls/{control}',
            'mqtt_status': 'Путь сформирован из WB ID; наличие публикации live не проверено',
            'input_token': control if re.fullmatch(r'(EXT\d+_)?IN\d+', control) else None,
            'address_inference': address, 'eim_module_channel': None,
            'binding_status': 'Проверено в экспорте',
            'physical_status': 'Не могу проверить: монтаж, клеммы и live отсутствуют',
            'meaning_status': 'Предположение по подписям; подписи сохранены дословно',
            'active_level': None, 'alarm_delay': None, 'installed_model': None,
            'occurrences': refs})
    plan_index, plan = next((i, d) for i, d in enumerate(dashboards) if d['id']=='Plan')
    svg = plan['svg']['current']
    xml = ET.fromstring(svg)
    texts = [{'element_id': e.get('id'), 'text': ''.join(e.itertext()).strip()}
             for e in xml.iter() if e.tag == '{http://www.w3.org/2000/svg}text']
    assert plan['svg']['params'] == []
    assert plan['svg']['original'] == {}
    assert not any(e.tag.endswith('}script') for e in xml.iter())
    assert not any('href' in k or k in ('onclick', 'onload', 'onmouseover') or k.startswith('data-')
                   for e in xml.iter() for k in e.attrib)
    obj = [c for c in channels if any(o['scope']=='object' for o in c['occurrences'])]
    service = [c for c in channels if c not in obj]
    counts = {'dashboards': len(dashboards), 'widgets': len(widgets),
              'widget_channel_occurrences': sum(o['kind']=='widget' for o in occurrences),
              'separator_cells': len(separators), 'svg_channel_occurrences': sum(o['kind']=='svg_param' for o in occurrences),
              'unique_channels': len(channels), 'object_channels': len(obj),
              'object_discrete_channels': sum(c['input_token'] is not None for c in obj),
              'demo_service_channels': len(service),
              'enabled_svg_write_occurrences': sum(o.get('mode')=='write' and o.get('enabled') is True for o in occurrences)}
    assert counts['object_discrete_channels'] == 98
    assert counts['object_channels'] == 100
    # Independent recursive inventory of literal channel reference fields.
    inventory = []
    def walk(value, pointer=''):
        if isinstance(value, dict):
            for k, v in value.items():
                p = pointer + '/' + k
                if k in ('id', 'channel') and isinstance(v, str) and '/' in v:
                    inventory.append((p, v))
                walk(v, p)
        elif isinstance(value, list):
            for i, v in enumerate(value):
                walk(v, pointer + '/' + str(i))
    walk(conf)
    assert Counter(inventory) == Counter((o['source_pointer'], o['wb_id']) for o in occurrences)
    data = {'object': '05 45 Фронтовых бригад', 'source': SOURCE,
            'source_sha256': sha, 'counts': counts, 'channels': channels,
            'excluded_separator_cells': separators}
    intro = f'''# Карта каналов — 05 45 Фронтовых бригад

Источник: [wb-webui (5).conf](Sources/wb-webui%20(5).conf). SHA256: `{sha}`.
Карта получена только из этого экспорта. Дата фиксации материалов: 2026-10-12; дата снятия экспорта неизвестна.

## Границы достоверности

- **Ф** — [Проверено] буквальная привязка и подпись есть в конфигурации WebUI. Это не подтверждение монтажа или работающего канала.
- **П** — [Предположение] физическое назначение следует из подписи; адрес устройства следует только из его имени.
- **Н** — [Не могу проверить] live, активный уровень, инверсия, NC/NO, задержка, клемма, модель модуля и связь со схемой неизвестны.
- MQTT-путь `/devices/<device>/controls/<control>` сформирован из WB ID; в экспорте это не отдельное поле и публикация брокером не проверена. Пробелы в control сохраняются.
- `MODULE.CHANNEL` по EIM пока не назначен: обозначений модулей DWG и кабельного журнала нет. `device_id.control_id` не подменяет проектный идентификатор.
- Тип `switch` — настройка отображения, а не свидетельство права записи, полярности или измеренного состояния.
- Для каждой строки действует **Ф / П / Н**. Поля `null` в JSON означают отсутствие сведений, не нулевое значение.

## Покрытие

{table(['Показатель','Количество'], counts.items())}

Все ссылки (включая отключённые SVG-привязки) сохранены в [channel_map.json](Doc/channel_map.json) с JSON Pointer и исходными полями. Разделители не являются каналами.

## Группы оборудования по подписям

Связь виджет → dashboard подтверждена в JSON; связь с физическим оборудованием требует сверки. Числа К1–К7 и ВО1–ВО14 — набор подписей, не подтверждённая ведомость оборудования. Не выводить число камер из числа МО.

'''
    groups=[]
    for w in widgets:
        if any(d['id'] in ('mo1','mo2','mo3','mo4') for d in membership[w['id']]):
            ids=[c['id'] for c in w['cells'] if c.get('type')!='separator']
            groups.append([w['id'],w['name'],', '.join(d['name'] for d in membership[w['id']]), ', '.join(dict.fromkeys(i.split('/')[0] for i in ids)),len(ids)])
    intro += table(['Виджет','Подпись дословно','Панель','device_id','Каналов'],groups)
    intro += '''

К6/К7 отнесены к МО4 по включению widget15/widget16 в dashboard `mo4`; в названиях самих виджетов МО не написано. «Камера 4» также находится на панели МО4, что не доказывает соответствие остальных камер номерам МО.

## Адреса и входы

`wb-gpio/EXT1_INx` и `EXT2_INx`: токены EXT1/EXT2 и номера входов прочитаны буквально. Это не Modbus-адреса. Соответствие физическим WBIO-DI-HVD16 и клеммам надо сверить с конфигурацией GPIO и монтажом.

`wb-mio-gpio_102:1`, `103:1`, `103:2`, `104:1`, `104:2`: числа 102/103/104 и 1/2 находятся в device_id. [Предположение] это адрес узла и номер модуля; реальные `slave_id`, порт RS-485 и состав модулей не подтверждены.

`wb-ms_156`: 156 — токен имени. [Предположение] адрес устройства; точную модель, серийный номер и место установки WebUI не устанавливает.

Во всех семи группах представлены входы 1–14. Наличие/занятость входов 15/16 по этому файлу неизвестны; считать их свободными нельзя. HP/LP здесь подписаны как дискретные аварии, а не числовые измерения давления. Аналоговые каналы давления в объектовых виджетах не найдены.

## Подробные объектовые каналы

JSON Pointer в последнем столбце относится к исходному конфигу. Все подписи сохранены без исправлений; для точного сохранения пробелов использовать JSON.

'''
    for w in widgets:
        entries=[(c,o) for c in obj for o in c['occurrences'] if o.get('widget_id')==w['id']]
        if entries:
            intro += f"### {w['id']} — {w['name']}\n\n"
            intro += table(['Раздел / сигнал дословно','WB ID','MQTT topic (выведен)','Достоверность','Источник'],
                [(o['section_label']+' / '+o['signal_label'],c['wb_id'],c['mqtt_topic_derived'],'Ф / П / Н',o['source_pointer']) for c,o in entries])+'\n\n'
    intro += '''## Демонстрационные и служебные каналы

Не входят в карту холодильного оборудования. Сохранены для полноты экспорта. Наличие ссылок на network/system не раскрывает фактические IP или serial контроллера.

В Demo SVG есть 26 включённых write-привязок к восьми уникальным каналам: `wb-gpio/A1_OUT`–`A4_OUT`, `5V_OUT`, `V_OUT`, `buzzer/enabled`, `system/Reboot`. Это факт настроек UI, а не доказательство подключения выходов к холодильным установкам. Исходник является архивом, не подготовленным для развёртывания интерфейсом «только мониторинг».

'''
    intro += table(['WB ID','MQTT topic (выведен)','Подписи / применения','Достоверность'],
        [(c['wb_id'],c['mqtt_topic_derived'],'; '.join(dict.fromkeys(o.get('signal_label','') or o.get('mode','') for o in c['occurrences'])),'Ф / Н') for c in service])+'\n'
    manifest={'object':'05 45 Фронтовых бригад','recorded_date':'2026-10-12',
        'source_filename':'wb-webui (5).conf','source_sha256':sha,'source_bytes':len(raw),
        'export_time':None,'controller_identity':None,'live_verified':False,
        'plan_source_pointer':f'/dashboards/{plan_index}/svg/current',
        'plan_sha256':hashlib.sha256(svg.encode('utf-8')).hexdigest(),
        'plan_original':plan['svg']['original'],'plan_params':plan['svg']['params'],
        'counts':counts}
    return {'Doc/channel_map.json':encoded(data), 'CHANNEL_MAP.md':intro.encode('utf-8'),
            'SVG/Plan.svg':svg.encode('utf-8'), 'SVG/Plan.dashboard.json':encoded(plan),
            'SVG/Plan.texts.json':encoded(texts), 'Sources/manifest.json':encoded(manifest)}


def main():
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--check',action='store_true')
    args=parser.parse_args()
    outputs=extract()
    for name, content in outputs.items():
        path=ROOT/name
        if args.check:
            assert path.read_bytes()==content, f'Generated file differs: {name}'
        else:
            path.parent.mkdir(parents=True,exist_ok=True)
            path.write_bytes(content)
    print(json.dumps({'mode':'check' if args.check else 'generate', 'files':len(outputs),
                      'counts':json.loads(outputs['Sources/manifest.json'])['counts']},ensure_ascii=False))


if __name__=='__main__':
    main()
